const eingabe = $input.first().json;
const workflow = eingabe.workflow || {};
const lauf = eingabe.execution || {};
const fehler = lauf.error || {};
const name = workflow.name || 'Unbekannter Workflow';
const speicher = $getWorkflowStaticData('global');
const jetzt = Date.now();
const frueher = speicher[name] || { zeit: 0, unterdrueckt: 0 };
if (jetzt - frueher.zeit < 600000) {
  speicher[name] = { zeit: frueher.zeit, unterdrueckt: frueher.unterdrueckt + 1 };
  return [];
}
const unterdrueckt = frueher.unterdrueckt;
speicher[name] = { zeit: jetzt, unterdrueckt: 0 };
const THEMEN = [[/^MDM/, 'Home-Lab-MDM'], [/Zammad|Nightly/, 'zammad'], [/WhatsApp/, 'whatsapp-relay']];
const treffer = THEMEN.find(([muster]) => muster.test(name));
const zeilen = [];
if (lauf.lastNodeExecuted) zeilen.push('Node: ' + lauf.lastNodeExecuted);
zeilen.push('Fehler: ' + String(fehler.message || 'unbekannt').slice(0, 600));
if (lauf.url) zeilen.push('Lauf: ' + lauf.url);
if (unterdrueckt > 0) zeilen.push(unterdrueckt + ' weitere Fehler dieses Workflows in den letzten 10 Minuten unterdrueckt.');
return [{
  json: {
    quelle: name,
    status: 'error',
    titel: 'Workflow fehlgeschlagen: ' + name,
    text: zeilen.join('\n'),
    prioritaet: 'high',
    tags: 'rotating_light',
    thema: treffer ? treffer[1] : 'Home-Lab-MDM',
    mail: /^MDM/.test(name) ? 'false' : 'true',
    kanal: /^MDM/.test(name) ? 'MDM-Verwaltung' : 'Berichte',
  },
}];
